import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";

const OrarSali = () => {
  const { sala } = useParams(); // Preluăm parametrii din URL

  useEffect(() => {
    if (sala) {
      // Fetch pentru orarul unei săli
      const url = `http://localhost:34101/orar/sala/${sala}`;
      fetch(url)
        .then((res) => res.json())
        .then((data) => {
          // Setează orarul pentru sala respectivă
        })
        .catch((err) => {
          console.error("Eroare la preluarea orarului pentru sală:", err);
        });
    }
  }, [sala]);

  return (
    <div>
      <h2>Orar pentru sala {sala}</h2>
      {/* Afișează orarul pentru sală */}
    </div>
  );
};

export default OrarSali;
